#!/usr/bin/env bash
set -euo pipefail

APP_ID=$(node -e "console.log(require('./capacitor.config.json').appId)")
MAIN=android/app/src/main
PKG_DIR="$MAIN/java/$(echo "$APP_ID" | tr . /)"

mkdir -p "$PKG_DIR" "$MAIN/res/layout" "$MAIN/res/xml" "$MAIN/res/drawable" "$MAIN/res/values"

# Files from older versions. android/ is regenerated by CI so this is mostly a
# safety net for local runs.
rm -f "$PKG_DIR/QuitWidgetProvider.java" \
      "$PKG_DIR/DaysWidgetProvider.java" \
      "$PKG_DIR/ClockWidgetProvider.java" \
      "$PKG_DIR/MoneyWidgetProvider.java" \
      "$PKG_DIR/AvoidedWidgetProvider.java" \
      "$PKG_DIR/CleanWidgetProvider.java" \
      "$MAIN/res/layout/widget_quit.xml" \
      "$MAIN/res/layout/widget_small.xml" \
      "$MAIN/res/layout/widget_tall.xml" \
      "$MAIN/res/layout/widget_wide.xml" \
      "$MAIN/res/layout/widget_strip.xml" \
      "$MAIN/res/layout/widget_large.xml" \
      "$MAIN/res/xml/quit_widget_info.xml" \
      "$MAIN/res/xml/days_widget_info.xml" \
      "$MAIN/res/xml/clock_widget_info.xml" \
      "$MAIN/res/xml/money_widget_info.xml" \
      "$MAIN/res/xml/avoided_widget_info.xml" \
      "$MAIN/res/xml/clean_widget_info.xml" \
      "$MAIN/res/drawable/widget_bg.xml" \
      "$MAIN/res/values/widget_strings.xml" 2>/dev/null || true

# ---------------------------------------------------------------------------
# Shared widget logic.
#
# Three widgets, all with the same 4x1 footprint as the Google search bar:
# `Days` (smoke count), `Streak` (the second habit) and `Both` (the two side by
# side). Each one reads its own settings - theme, accent and which figure to
# show - from `unlit_widget_settings`, keyed by widget id, so two copies of the
# same widget can look different.
#
# Values come from the web layer through @capacitor/preferences
# (SharedPreferences file "CapacitorStorage", raw keys).
# ---------------------------------------------------------------------------
cat > "$PKG_DIR/QuiterWidgetBase.java" <<'EOF'
package __APP_ID__;

import android.app.PendingIntent;
import android.appwidget.AppWidgetManager;
import android.appwidget.AppWidgetProvider;
import android.appwidget.AppWidgetProviderInfo;
import android.content.ComponentName;
import android.content.Context;
import android.content.Intent;
import android.content.SharedPreferences;
import android.content.res.Configuration;
import android.os.Bundle;
import android.util.TypedValue;
import android.widget.RemoteViews;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.Locale;
import org.json.JSONArray;
import org.json.JSONObject;

/**
 * One row of pixels, same size as the Google search bar.
 *
 * The bar is fixed at 4x1: {dot} {number over tiny caption} ... {supporting
 * figure}. `Both` puts two such groups side by side. Nothing on the bar names
 * the habit; the widget only ever shows a plain count.
 */
public abstract class QuiterWidgetBase extends AppWidgetProvider {
    public static final String ACTION_REFRESH = "com.unlit.app.REFRESH_WIDGET";

    static final String PREFS = "CapacitorStorage";
    static final String SETTINGS = "unlit_widget_settings";
    static final String KEY_PENDING = "unlit_pending_logs";

    public static final int MODE_SMOKE = 0;
    public static final int MODE_FAP = 1;
    public static final int MODE_BOTH = 2;

    public static final int SHOW_DAYS = 0;
    public static final int SHOW_TIME = 1;
    public static final int SHOW_SAVED = 2;
    public static final int SHOW_COUNT = 3;

    protected abstract int mode();

    @Override
    public void onUpdate(Context context, AppWidgetManager manager, int[] ids) {
        updateAll(context, manager, ids, mode());
    }

    @Override
    public void onAppWidgetOptionsChanged(Context context, AppWidgetManager manager, int id, Bundle options) {
        // The footprint is fixed, but a launcher may still send a size change
        // (rotation, grid change); repaint so it never goes stale.
        updateOne(context, manager, id, mode());
    }

    @Override
    public void onReceive(Context context, Intent intent) {
        super.onReceive(context, intent);
        if (intent != null && ACTION_REFRESH.equals(intent.getAction())) {
            refreshAll(context);
        }
    }

    /** Rebuilds every placed widget of every kind. Safe when none are placed. */
    public static void refreshAll(Context context) {
        try {
            Context app = context.getApplicationContext();
            AppWidgetManager manager = AppWidgetManager.getInstance(app);
            updateAll(app, manager, manager.getAppWidgetIds(new ComponentName(app, SmokeWidgetProvider.class)), MODE_SMOKE);
            updateAll(app, manager, manager.getAppWidgetIds(new ComponentName(app, FapWidgetProvider.class)), MODE_FAP);
            updateAll(app, manager, manager.getAppWidgetIds(new ComponentName(app, BothWidgetProvider.class)), MODE_BOTH);
        } catch (Throwable ignored) {
            // Never let a widget failure break the caller.
        }
    }

    /** Repaints one instance after its settings change. */
    public static void updateNow(Context context, int id) {
        try {
            AppWidgetManager manager = AppWidgetManager.getInstance(context);
            AppWidgetProviderInfo info = manager.getAppWidgetInfo(id);
            String cls = info != null && info.provider != null ? info.provider.getClassName() : "";
            manager.updateAppWidget(id, build(context, id, modeFor(cls)));
        } catch (Throwable ignored) {
            // The launcher keeps the last good bar.
        }
    }

    static int modeFor(String className) {
        if (className != null && className.endsWith("FapWidgetProvider")) return MODE_FAP;
        if (className != null && className.endsWith("BothWidgetProvider")) return MODE_BOTH;
        return MODE_SMOKE;
    }

    static String key(int id, String name) {
        return "widget_" + id + "_" + name;
    }

    static SharedPreferences settings(Context context) {
        return context.getSharedPreferences(SETTINGS, Context.MODE_PRIVATE);
    }

    /** Queues a count logged from the widget for the web app to import. */
    public static void appendPendingLog(Context context, int count) {
        try {
            SharedPreferences sp = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE);
            JSONArray arr = new JSONArray();
            String raw = sp.getString(KEY_PENDING, "");
            if (raw != null && raw.length() > 0) {
                try {
                    arr = new JSONArray(raw);
                } catch (Throwable ignored) {
                    arr = new JSONArray();
                }
            }
            JSONObject item = new JSONObject();
            long now = System.currentTimeMillis();
            item.put("id", "widget_" + now);
            item.put("ts", now);
            item.put("count", Math.max(1, Math.min(99, count)));
            arr.put(item);
            sp.edit().putString(KEY_PENDING, arr.toString()).commit();
        } catch (Throwable ignored) {
            // The dialog still closes; the app just misses this one.
        }
    }

    private static void updateAll(Context context, AppWidgetManager manager, int[] ids, int mode) {
        if (ids == null) return;
        for (int id : ids) {
            updateOne(context, manager, id, mode);
        }
    }

    private static void updateOne(Context context, AppWidgetManager manager, int id, int mode) {
        try {
            manager.updateAppWidget(id, build(context, id, mode));
        } catch (Throwable ignored) {
            // Keep the other instances alive.
        }
    }

    static final class Data {
        long quit;
        double perDay;
        double packSize = 20;
        double packCost;
        String currency = "\u09F3";
        long logged;
        long elapsed;
        long days;
        long hours;
        long mins;
        long avoided;
        double saved;
        String since = "";

        // Second habit (the `Streak` widget).
        long fapQuit;
        long fapSlips;
        long fapElapsed;
        long fapDays;
        String fapShort = "";
        String fapSince = "";
    }

    private static Data read(Context context) {
        Data d = new Data();
        try {
            SharedPreferences sp = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE);
            d.quit = parseLong(sp.getString("unlit_quit_date", ""), 0L);
            d.perDay = parseDouble(sp.getString("unlit_cigs_per_day", ""), 0);
            d.packSize = parseDouble(sp.getString("unlit_pack_size", ""), 20);
            d.packCost = parseDouble(sp.getString("unlit_pack_cost", ""), 0);
            d.logged = parseLong(sp.getString("unlit_logged_total", ""), 0L);
            d.fapQuit = parseLong(sp.getString("unlit_fap_start", ""), 0L);
            d.fapSlips = parseLong(sp.getString("unlit_fap_slips", ""), 0L);
            String cur = sp.getString("unlit_currency", "\u09F3");
            if (cur != null && cur.length() > 0) d.currency = cur;
        } catch (Throwable ignored) {
            // Unreadable prefs: the setup state below is still valid.
        }

        if (d.quit > 0L) {
            d.elapsed = Math.max(0L, System.currentTimeMillis() - d.quit);
            d.days = d.elapsed / 86400000L;
            d.hours = (d.elapsed % 86400000L) / 3600000L;
            d.mins = (d.elapsed % 3600000L) / 60000L;
            double daysExact = d.elapsed / 86400000.0;
            long baseline = (long) Math.floor(daysExact * d.perDay);
            d.avoided = Math.max(0L, baseline - d.logged);
            d.saved = d.packSize > 0 ? (d.avoided / d.packSize) * d.packCost : 0;
            try {
                d.since = new SimpleDateFormat("MMM d", Locale.US).format(new Date(d.quit)).toUpperCase(Locale.US);
            } catch (Throwable ignored) {
                d.since = "";
            }
        }

        if (d.fapQuit > 0L) {
            d.fapElapsed = Math.max(0L, System.currentTimeMillis() - d.fapQuit);
            d.fapDays = d.fapElapsed / 86400000L;
            long fh = (d.fapElapsed % 86400000L) / 3600000L;
            long fm = (d.fapElapsed % 3600000L) / 60000L;
            if (d.fapElapsed >= 86400000L) d.fapShort = d.fapDays + "d " + fh + "h";
            else if (d.fapElapsed >= 3600000L) d.fapShort = fh + "h " + two(fm) + "m";
            else d.fapShort = fm + "m";
            try {
                d.fapSince = new SimpleDateFormat("MMM d", Locale.US)
                        .format(new Date(d.fapQuit)).toUpperCase(Locale.US);
            } catch (Throwable ignored) {
                d.fapSince = "";
            }
        }
        return d;
    }

    /** "\u09F3 1,240" - the savings figure, rounded to whole units. */
    static String money(Data d) {
        return d.currency + String.format(Locale.US, "%,.0f", d.saved);
    }

    /** "8m", "5h 42m", "12d 4h" */
    static String elapsedShort(Data d) {
        if (d.elapsed >= 86400000L) return d.days + "d " + d.hours + "h";
        if (d.elapsed >= 3600000L) return d.hours + "h " + two(d.mins) + "m";
        return d.mins + "m";
    }

    /** "12d 4h 05m" */
    static String elapsedLong(Data d) {
        if (d.elapsed >= 86400000L) return d.days + "d " + d.hours + "h " + two(d.mins) + "m";
        if (d.elapsed >= 3600000L) return d.hours + "h " + two(d.mins) + "m";
        return d.mins + "m";
    }

    private static String two(long n) {
        return n < 10 ? "0" + n : String.valueOf(n);
    }

    private static boolean isNight(Context context) {
        int mask = context.getResources().getConfiguration().uiMode & Configuration.UI_MODE_NIGHT_MASK;
        return mask == Configuration.UI_MODE_NIGHT_YES;
    }

    private static int accentColor(String name, boolean night) {
        if ("green".equals(name)) return 0xFF34C759;
        if ("amber".equals(name)) return 0xFFF5A623;
        if ("blue".equals(name)) return 0xFF3B82F6;
        return night ? 0xFF8A8A8A : 0xFF71717A;
    }

    private static float heroSize(String text) {
        int length = text == null ? 0 : text.length();
        if (length >= 10) return 15f;
        if (length >= 8) return 17f;
        if (length >= 6) return 19f;
        return 23f;
    }

    private static String days(long value) {
        return value + (value == 1L ? " DAY" : " DAYS");
    }

    private static RemoteViews build(Context context, int id, int mode) {
        Data d = read(context);
        SharedPreferences wp = settings(context);
        String theme = wp.getString(key(id, "theme"), "auto");
        String accentName = wp.getString(key(id, "accent"), "mono");
        int display = wp.getInt(key(id, "display"), SHOW_DAYS);

        boolean night = "dark".equals(theme) || ("auto".equals(theme) && isNight(context));
        int fg = night ? 0xFFFFFFFF : 0xFF0A0A0A;
        int muted = night ? 0xFF8A8A8A : 0xFF71717A;
        int line = night ? 0xFF2E2E2E : 0xFFE4E4E7;
        int accent = accentColor(accentName, night);
        int bg = night ? R.drawable.widget_bg_dark : R.drawable.widget_bg_light;

        boolean hasSmoke = d.quit > 0L;
        boolean hasFap = d.fapQuit > 0L;

        if (mode == MODE_BOTH) {
            RemoteViews v = new RemoteViews(context.getPackageName(), R.layout.widget_bar_both);
            v.setInt(R.id.widget_root, "setBackgroundResource", bg);
            v.setTextColor(R.id.dot1, accent);
            v.setTextColor(R.id.dot2, accent);
            v.setTextColor(R.id.hero1, fg);
            v.setTextColor(R.id.hero2, fg);
            v.setTextColor(R.id.label1, muted);
            v.setTextColor(R.id.label2, muted);
            v.setInt(R.id.divider, "setBackgroundColor", line);

            String hero1 = hasSmoke ? String.valueOf(d.days) : "--";
            String hero2 = hasFap ? String.valueOf(d.fapDays) : "--";
            v.setTextViewText(R.id.hero1, hero1);
            v.setTextViewText(R.id.hero2, hero2);
            v.setTextViewText(R.id.label1, hasSmoke ? (d.days == 1L ? "DAY" : "DAYS") : "DAYS");
            v.setTextViewText(R.id.label2, hasFap ? (d.fapDays == 1L ? "DAY" : "STREAK") : "STREAK");
            v.setTextViewTextSize(R.id.hero1, TypedValue.COMPLEX_UNIT_SP, 20f);
            v.setTextViewTextSize(R.id.hero2, TypedValue.COMPLEX_UNIT_SP, 20f);

            setRootClick(context, v);
            return v;
        }

        RemoteViews v = new RemoteViews(context.getPackageName(), R.layout.widget_bar);
        v.setInt(R.id.widget_root, "setBackgroundResource", bg);
        v.setTextColor(R.id.dot, accent);
        v.setTextColor(R.id.hero, fg);
        v.setTextColor(R.id.label, muted);
        v.setTextColor(R.id.sub, muted);

        String hero;
        String label;
        String sub;

        if (mode == MODE_FAP) {
            // Deliberately neutral wording: this sits on a home screen other
            // people can see.
            if (!hasFap) {
                hero = "--";
                label = "STREAK";
                sub = "";
            } else if (display == SHOW_TIME) {
                hero = d.fapShort;
                label = "TIME";
                sub = "SINCE " + d.fapSince;
            } else {
                hero = String.valueOf(d.fapDays);
                label = d.fapDays == 1L ? "DAY" : "STREAK";
                sub = "SINCE " + d.fapSince;
            }
        } else if (!hasSmoke) {
            hero = "--";
            label = "DAYS";
            sub = "";
        } else if (display == SHOW_TIME) {
            hero = elapsedShort(d);
            label = "TIME";
            sub = "SINCE " + d.since;
        } else if (display == SHOW_SAVED) {
            hero = money(d);
            label = "SAVED";
            sub = "SINCE " + d.since;
        } else if (display == SHOW_COUNT) {
            hero = String.format(Locale.US, "%,d", d.avoided);
            label = "AVOIDED";
            sub = "SINCE " + d.since;
        } else {
            hero = String.valueOf(d.days);
            label = d.days == 1L ? "DAY" : "DAYS";
            sub = d.quit > 0L ? days(d.days) : "";
        }

        v.setTextViewText(R.id.hero, hero);
        v.setTextViewText(R.id.label, label);
        v.setTextViewText(R.id.sub, sub);
        v.setTextViewTextSize(R.id.hero, TypedValue.COMPLEX_UNIT_SP, heroSize(hero));

        setRootClick(context, v);
        if (mode == MODE_SMOKE) {
            try {
                // Tapping the number logs a count right there; the rest of the
                // bar opens the app.
                Intent log = new Intent(context, SmokeQuickLogActivity.class);
                log.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_CLEAR_TOP);
                PendingIntent logDialog = PendingIntent.getActivity(context, 1, log,
                        PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE);
                v.setOnClickPendingIntent(R.id.hero, logDialog);
            } catch (Throwable ignored) {
                // Tapping still opens the app.
            }
        }
        return v;
    }

    private static void setRootClick(Context context, RemoteViews v) {
        try {
            Intent launch = context.getPackageManager().getLaunchIntentForPackage(context.getPackageName());
            if (launch != null) {
                PendingIntent openApp = PendingIntent.getActivity(context, 0, launch,
                        PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE);
                v.setOnClickPendingIntent(R.id.widget_root, openApp);
            }
        } catch (Throwable ignored) {
            // Tapping does nothing rather than crashing the launcher.
        }
    }

    private static long parseLong(String s, long fallback) {
        if (s == null) return fallback;
        try { return Long.parseLong(s.trim()); } catch (Exception e) { return fallback; }
    }

    private static double parseDouble(String s, double fallback) {
        if (s == null) return fallback;
        try { return Double.parseDouble(s.trim()); } catch (Exception e) { return fallback; }
    }
}
EOF
sed -i "s/__APP_ID__/$APP_ID/g" "$PKG_DIR/QuiterWidgetBase.java"

cat > "$PKG_DIR/SmokeWidgetProvider.java" <<'EOF'
package __APP_ID__;

/** The plain day-count bar for the smoke tracker. */
public class SmokeWidgetProvider extends QuiterWidgetBase {
    @Override
    protected int mode() {
        return MODE_SMOKE;
    }
}
EOF
sed -i "s/__APP_ID__/$APP_ID/g" "$PKG_DIR/SmokeWidgetProvider.java"

cat > "$PKG_DIR/FapWidgetProvider.java" <<'EOF'
package __APP_ID__;

/** The plain streak bar for the second habit. */
public class FapWidgetProvider extends QuiterWidgetBase {
    @Override
    protected int mode() {
        return MODE_FAP;
    }
}
EOF
sed -i "s/__APP_ID__/$APP_ID/g" "$PKG_DIR/FapWidgetProvider.java"

cat > "$PKG_DIR/BothWidgetProvider.java" <<'EOF'
package __APP_ID__;

/** Both counts side by side in one Google-search-bar footprint. */
public class BothWidgetProvider extends QuiterWidgetBase {
    @Override
    protected int mode() {
        return MODE_BOTH;
    }
}
EOF
sed -i "s/__APP_ID__/$APP_ID/g" "$PKG_DIR/BothWidgetProvider.java"

# ---------------------------------------------------------------------------
# Per-widget settings. Android opens this when the widget is placed (and again
# when it is reconfigured from the launcher). Every instance stores its own
# theme, accent and displayed figure.
# ---------------------------------------------------------------------------
cat > "$PKG_DIR/WidgetConfigActivity.java" <<'EOF'
package __APP_ID__;

import android.app.Activity;
import android.appwidget.AppWidgetManager;
import android.appwidget.AppWidgetProviderInfo;
import android.content.Intent;
import android.content.SharedPreferences;
import android.content.res.Configuration;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.view.Gravity;
import android.view.View;
import android.view.ViewGroup;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;
import java.util.ArrayList;
import java.util.List;

/** Settings sheet for one placed widget: theme, accent, and what it shows. */
public class WidgetConfigActivity extends Activity {
    private int widgetId = AppWidgetManager.INVALID_APPWIDGET_ID;
    private int mode = QuiterWidgetBase.MODE_SMOKE;

    private int themeIndex = 0;
    private int accentIndex = 0;
    private int displayIndex = 0;

    private static final String[] THEME_VALUES = {"auto", "light", "dark"};
    private static final String[] ACCENT_VALUES = {"mono", "green", "amber", "blue"};

    private final List<TextView> themePills = new ArrayList<>();
    private final List<TextView> accentPills = new ArrayList<>();
    private final List<TextView> displayPills = new ArrayList<>();

    private boolean night;
    private int fg;
    private int muted;
    private int line;
    private int field;

    @Override
    protected void onCreate(Bundle state) {
        super.onCreate(state);
        setResult(RESULT_CANCELED);

        widgetId = getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,
                AppWidgetManager.INVALID_APPWIDGET_ID);
        if (widgetId == AppWidgetManager.INVALID_APPWIDGET_ID) {
            finish();
            return;
        }

        AppWidgetManager manager = AppWidgetManager.getInstance(this);
        AppWidgetProviderInfo info = manager.getAppWidgetInfo(widgetId);
        String cls = info != null && info.provider != null ? info.provider.getClassName() : "";
        mode = QuiterWidgetBase.modeFor(cls);

        SharedPreferences sp = QuiterWidgetBase.settings(this);
        String theme = sp.getString(QuiterWidgetBase.key(widgetId, "theme"), "auto");
        String accent = sp.getString(QuiterWidgetBase.key(widgetId, "accent"), "mono");
        int display = sp.getInt(QuiterWidgetBase.key(widgetId, "display"), QuiterWidgetBase.SHOW_DAYS);

        for (int i = 0; i < THEME_VALUES.length; i++) {
            if (THEME_VALUES[i].equals(theme)) themeIndex = i;
        }
        for (int i = 0; i < ACCENT_VALUES.length; i++) {
            if (ACCENT_VALUES[i].equals(accent)) accentIndex = i;
        }
        displayIndex = Math.max(0, Math.min(maxDisplayIndex(), display));

        night = (getResources().getConfiguration().uiMode & Configuration.UI_MODE_NIGHT_MASK)
                == Configuration.UI_MODE_NIGHT_YES;
        fg = night ? 0xFFFFFFFF : 0xFF0A0A0A;
        muted = night ? 0xFF8A8A8A : 0xFF71717A;
        line = night ? 0xFF2E2E2E : 0xFFE4E4E7;
        field = night ? 0xFF141414 : 0xFFF4F4F5;

        ScrollView scroll = new ScrollView(this);
        scroll.setFillViewport(true);
        LinearLayout root = new LinearLayout(this);
        root.setOrientation(LinearLayout.VERTICAL);
        int pad = dp(22);
        root.setPadding(pad, pad, pad, pad);
        GradientDrawable card = new GradientDrawable();
        card.setColor(night ? 0xFF0A0A0A : 0xFFFFFFFF);
        card.setCornerRadius(dp(26));
        card.setStroke(dp(1), line);
        root.setBackground(card);
        scroll.addView(root);

        TextView title = new TextView(this);
        title.setText("Widget settings");
        title.setTextColor(fg);
        title.setTextSize(20);
        title.setTypeface(title.getTypeface(), Typeface.BOLD);
        root.addView(title);

        TextView caption = new TextView(this);
        caption.setText(mode == QuiterWidgetBase.MODE_BOTH
                ? "Two counters in one bar"
                : "One bar, your numbers");
        caption.setTextColor(muted);
        caption.setTextSize(13);
        LinearLayout.LayoutParams captionParams = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        captionParams.topMargin = dp(4);
        root.addView(caption, captionParams);

        section(root, "Appearance");
        row(root, themePills, new String[]{"Auto", "Light", "Dark"}, new int[]{0, 1, 2});

        section(root, "Accent");
        row(root, accentPills, new String[]{"Mono", "Green", "Amber", "Blue"}, new int[]{0, 1, 2, 3});

        if (mode != QuiterWidgetBase.MODE_BOTH) {
            section(root, "Shows");
            if (mode == QuiterWidgetBase.MODE_FAP) {
                row(root, displayPills, new String[]{"Days", "Time"}, new int[]{0, 1});
            } else {
                row(root, displayPills,
                        new String[]{"Days", "Time", "Saved", "Count"},
                        new int[]{0, 1, 2, 3});
            }
        }

        LinearLayout buttons = new LinearLayout(this);
        buttons.setOrientation(LinearLayout.HORIZONTAL);
        LinearLayout.LayoutParams buttonsParams = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        buttonsParams.topMargin = dp(22);

        TextView cancel = pill("Cancel", false);
        TextView save = pill("Save", true);
        LinearLayout.LayoutParams left = new LinearLayout.LayoutParams(0, dp(50), 1f);
        left.rightMargin = dp(8);
        LinearLayout.LayoutParams right = new LinearLayout.LayoutParams(0, dp(50), 1f);
        buttons.addView(cancel, left);
        buttons.addView(save, right);
        root.addView(buttons, buttonsParams);

        cancel.setOnClickListener(v -> finish());
        save.setOnClickListener(v -> save());

        setContentView(scroll);
        refreshSelection();
    }

    private int maxDisplayIndex() {
        return mode == QuiterWidgetBase.MODE_FAP ? 1 : 3;
    }

    private void section(LinearLayout root, String text) {
        TextView label = new TextView(this);
        label.setText(text.toUpperCase());
        label.setTextColor(muted);
        label.setTextSize(10);
        label.setLetterSpacing(0.10f);
        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        params.topMargin = dp(20);
        params.bottomMargin = dp(8);
        root.addView(label, params);
    }

    private void row(LinearLayout root, List<TextView> pills, String[] labels, int[] values) {
        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        for (int i = 0; i < labels.length; i++) {
            final int value = values[i];
            TextView tv = pill(labels[i], false);
            tv.setOnClickListener(v -> {
                if (pills == themePills) themeIndex = value;
                else if (pills == accentPills) accentIndex = value;
                else displayIndex = value;
                refreshSelection();
            });
            pills.add(tv);
            LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(0, dp(42), 1f);
            if (i > 0) params.leftMargin = dp(6);
            row.addView(tv, params);
        }
        root.addView(row, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
    }

    private TextView pill(String text, boolean primary) {
        TextView tv = new TextView(this);
        tv.setText(text);
        tv.setGravity(Gravity.CENTER);
        tv.setTextSize(13);
        tv.setTypeface(tv.getTypeface(), Typeface.BOLD);
        GradientDrawable shape = new GradientDrawable();
        shape.setCornerRadius(dp(21));
        if (primary) {
            shape.setColor(night ? 0xFFFFFFFF : 0xFF0A0A0A);
            tv.setTextColor(night ? 0xFF0A0A0A : 0xFFFFFFFF);
        } else {
            shape.setColor(field);
            tv.setTextColor(fg);
        }
        tv.setBackground(shape);
        tv.setClickable(true);
        return tv;
    }

    private void refreshSelection() {
        paint(themePills, themeIndex);
        paint(accentPills, accentIndex);
        paint(displayPills, displayIndex);
    }

    private void paint(List<TextView> pills, int selected) {
        for (int i = 0; i < pills.size(); i++) {
            TextView tv = pills.get(i);
            boolean on = i == selected;
            GradientDrawable shape = new GradientDrawable();
            shape.setCornerRadius(dp(21));
            shape.setColor(on ? (night ? 0xFFFFFFFF : 0xFF0A0A0A) : field);
            shape.setStroke(dp(1), on ? (night ? 0xFFFFFFFF : 0xFF0A0A0A) : line);
            tv.setBackground(shape);
            tv.setTextColor(on ? (night ? 0xFF0A0A0A : 0xFFFFFFFF) : fg);
        }
    }

    private void save() {
        SharedPreferences.Editor editor = QuiterWidgetBase.settings(this).edit();
        editor.putString(QuiterWidgetBase.key(widgetId, "theme"), THEME_VALUES[themeIndex]);
        editor.putString(QuiterWidgetBase.key(widgetId, "accent"), ACCENT_VALUES[accentIndex]);
        if (mode != QuiterWidgetBase.MODE_BOTH) {
            editor.putInt(QuiterWidgetBase.key(widgetId, "display"), displayIndex);
        }
        editor.apply();

        QuiterWidgetBase.updateNow(this, widgetId);
        Intent result = new Intent();
        result.putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID, widgetId);
        setResult(RESULT_OK, result);
        finish();
    }

    private int dp(int value) {
        return Math.round(value * getResources().getDisplayMetrics().density);
    }
}
EOF
