# ---------------------------------------------------------------------------
# Native "how many?" dialog for the smoke bar. A widget cannot host an
# EditText, so tapping the number opens this instead. It queues the count in
# CapacitorStorage and the web app imports it on the next open.
# ---------------------------------------------------------------------------
cat > "$PKG_DIR/SmokeQuickLogActivity.java" <<'EOF'
package __APP_ID__;

import android.app.Activity;
import android.content.res.Configuration;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.text.InputType;
import android.view.Gravity;
import android.view.ViewGroup;
import android.view.WindowManager;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.TextView;

/** Small dark/light dialog used by the day-count bar. */
public class SmokeQuickLogActivity extends Activity {
    @Override
    protected void onCreate(Bundle state) {
        super.onCreate(state);
        setFinishOnTouchOutside(true);

        boolean night = (getResources().getConfiguration().uiMode & Configuration.UI_MODE_NIGHT_MASK)
                == Configuration.UI_MODE_NIGHT_YES;
        int fg = night ? 0xFFFFFFFF : 0xFF0A0A0A;
        int muted = night ? 0xFF8A8A8A : 0xFF71717A;
        int card = night ? 0xFF0A0A0A : 0xFFFFFFFF;
        int line = night ? 0xFF2E2E2E : 0xFFE4E4E7;
        int field = night ? 0xFF141414 : 0xFFF4F4F5;

        LinearLayout root = new LinearLayout(this);
        root.setOrientation(LinearLayout.VERTICAL);
        int pad = dp(22);
        root.setPadding(pad, pad, pad, pad);
        GradientDrawable bg = new GradientDrawable();
        bg.setColor(card);
        bg.setCornerRadius(dp(26));
        bg.setStroke(dp(1), line);
        root.setBackground(bg);

        TextView title = new TextView(this);
        title.setText("Add a count");
        title.setTextColor(fg);
        title.setTextSize(20);
        title.setTypeface(title.getTypeface(), android.graphics.Typeface.BOLD);
        root.addView(title);

        TextView sub = new TextView(this);
        sub.setText("How many?");
        sub.setTextColor(muted);
        sub.setTextSize(13);
        LinearLayout.LayoutParams subParams = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        subParams.topMargin = dp(4);
        root.addView(sub, subParams);

        EditText input = new EditText(this);
        input.setInputType(InputType.TYPE_CLASS_NUMBER);
        input.setText("1");
        input.setSelectAllOnFocus(true);
        input.setTextColor(fg);
        input.setTextSize(22);
        input.setGravity(Gravity.CENTER);
        input.setHintTextColor(muted);
        GradientDrawable fieldBg = new GradientDrawable();
        fieldBg.setColor(field);
        fieldBg.setCornerRadius(dp(16));
        fieldBg.setStroke(dp(1), line);
        input.setBackground(fieldBg);
        LinearLayout.LayoutParams inputParams = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, dp(60));
        inputParams.topMargin = dp(16);
        root.addView(input, inputParams);

        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        LinearLayout.LayoutParams rowParams = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        rowParams.topMargin = dp(16);

        TextView cancel = pill("Cancel", false, fg, line, night);
        TextView save = pill("Add", true, fg, line, night);
        LinearLayout.LayoutParams leftParams = new LinearLayout.LayoutParams(0, dp(52), 1f);
        leftParams.rightMargin = dp(8);
        LinearLayout.LayoutParams rightParams = new LinearLayout.LayoutParams(0, dp(52), 1f);
        row.addView(cancel, leftParams);
        row.addView(save, rightParams);
        root.addView(row, rowParams);

        cancel.setOnClickListener(v -> finish());
        save.setOnClickListener(v -> {
            int count = 1;
            try {
                count = Integer.parseInt(input.getText().toString().trim());
            } catch (Throwable ignored) {
                count = 0;
            }
            if (count > 0) {
                QuiterWidgetBase.appendPendingLog(this, count);
                QuiterWidgetBase.refreshAll(this);
            }
            finish();
        });

        setContentView(root);
        input.requestFocus();
        if (getWindow() != null) {
            getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_VISIBLE);
        }
    }

    private TextView pill(String text, boolean primary, int fg, int line, boolean night) {
        TextView tv = new TextView(this);
        tv.setText(text);
        tv.setGravity(Gravity.CENTER);
        tv.setTextSize(15);
        tv.setTypeface(tv.getTypeface(), android.graphics.Typeface.BOLD);
        GradientDrawable shape = new GradientDrawable();
        shape.setCornerRadius(dp(26));
        if (primary) {
            shape.setColor(night ? 0xFFFFFFFF : 0xFF0A0A0A);
            tv.setTextColor(night ? 0xFF0A0A0A : 0xFFFFFFFF);
        } else {
            shape.setColor(0x00000000);
            shape.setStroke(dp(1), line);
            tv.setTextColor(fg);
        }
        tv.setBackground(shape);
        tv.setClickable(true);
        return tv;
    }

    private int dp(int value) {
        return Math.round(value * getResources().getDisplayMetrics().density);
    }
}
