# Drop any receiver or activity from an earlier version, then add the three
# widgets, their settings sheet and the quick-log dialog.
python3 - "$MANIFEST" <<'PY'
import re, sys
path = sys.argv[1]
src = open(path, encoding='utf-8').read()

src = re.sub(
    r'\s*<receiver\b[^>]*?android:name="\.[A-Za-z]*WidgetProvider".*?</receiver>',
    '', src, flags=re.S)
src = re.sub(
    r'\s*<activity\b[^>]*?android:name="\.WidgetConfigActivity".*?(?:/>|</activity>)',
    '', src, flags=re.S)
src = re.sub(
    r'\s*<activity\b[^>]*?android:name="\.SmokeQuickLogActivity".*?(?:/>|</activity>)',
    '', src, flags=re.S)

widgets = [
    ('SmokeWidgetProvider', 'widget_days_name', 'smoke_widget_info'),
    ('FapWidgetProvider', 'widget_streak_name', 'fap_widget_info'),
    ('BothWidgetProvider', 'widget_both_name', 'both_widget_info'),
]
receivers = ''
for cls, label, info in widgets:
    receivers += f'''
        <receiver
            android:name=".{cls}"
            android:exported="true"
            android:label="@string/{label}">
            <intent-filter>
                <action android:name="android.appwidget.action.APPWIDGET_UPDATE" />
                <action android:name="com.unlit.app.REFRESH_WIDGET" />
            </intent-filter>
            <meta-data
                android:name="android.appwidget.provider"
                android:resource="@xml/{info}" />
        </receiver>
'''

receivers += '''
        <activity
            android:name=".WidgetConfigActivity"
            android:exported="true"
            android:excludeFromRecents="true"
            android:theme="@style/QuiterQuickLog">
            <intent-filter>
                <action android:name="android.appwidget.action.APPWIDGET_CONFIGURE" />
            </intent-filter>
        </activity>

        <activity
            android:name=".SmokeQuickLogActivity"
            android:exported="false"
            android:excludeFromRecents="true"
            android:theme="@style/QuiterQuickLog"
            android:windowSoftInputMode="stateVisible|adjustResize" />
'''

if '</application>' not in src:
    raise SystemExit('AndroidManifest.xml has no </application> to insert into')
src = re.sub(r'[ \t]*</application>', lambda m: receivers + '    </application>', src, count=1)
open(path, 'w', encoding='utf-8').write(src)
PY

